// Package manifest decides "which version to download, from where, and with what checksum".
//
// The concrete tags and SHA-256s live in assets.gen.go (generated by scripts/gen-deps-manifest.mjs);
// this file only holds the lookup logic. Versions are pinned, not "latest": installs must be reproducible and verifiable.
package manifest

import (
	"fmt"
	"path/filepath"
	goruntime "runtime"

	"github.com/ShahzaibRao/downpilot/backend/internal/fetch"
	rt "github.com/ShahzaibRao/downpilot/backend/internal/runtime"
)

// MinYtDlpVersion is the threshold for judging yt-dlp "too old" — it equals the manifest-pinned tag.
//
// Why not just compare the year like before (MinimumMajor = 2024): yt-dlp uses **date versions**,
// and site fixes ship weekly. The 2026.08.19 build was observed failing YouTube with
// `Requested format is not available` (upstream fixed the same class of issue in a newer build),
// while a year-based check would "pass" it — leaving users stuck on a build that can't run.
//
// The threshold is **the manifest-pinned version**: it's what we'd download anyway, so lagging means re-download.
// This keeps "detection says usable" and "actually downloadable" on the same standard.
func MinYtDlpVersion() string { return YtDlpTag }

// MinGalleryDlVersion: gallery-dl is likewise a date-versioned nightly; the manifest-pinned tag is the threshold
func MinGalleryDlVersion() string { return GalleryDlTag }

// MinDenoVersion: deno uses semver (v2.9.7); CompareVersions compares numeric segments, so the "v" prefix doesn't matter
func MinDenoVersion() string { return DenoTag }

// Platforms are the supported platform combos, for CI cross-builds and verification
var Platforms = []string{"darwin/arm64", "darwin/x64", "linux/x64", "linux/arm64", "win32/x64"}

// asset is a downloadable artifact: the upstream file name and the SHA-256 of the downloaded bytes.
// For gzip artifacts the checksum covers the archive itself (verify on download, before extracting).
type asset struct {
	Name   string
	SHA256 string
}

// CurrentPlatform is the current platform, keyed like electron-builder's ${platform}-${arch}.
//
// **Do NOT use Go's GOOS/GOARCH directly**: Go says windows/amd64, electron-builder says
// win32/x64. The asset table uses the latter naming; using Go's values verbatim means the table
// is never found on Windows (erroring "no downloads for windows/amd64"), while macOS/Linux happen
// to use identical naming so the problem stays invisible — this bug only shows on Windows.
func CurrentPlatform() string {
	return PlatformKey(goruntime.GOOS, goruntime.GOARCH)
}

// PlatformKey maps Go's GOOS/GOARCH to electron-builder's platform key.
//
// It's a pure function taking parameters so the Windows mapping can be tested **on macOS** —
// it used to read the global GOOS/GOARCH, so tests could only assert `if runtime.GOOS == "windows"`,
// which meant this Windows-only bug could never be caught locally (verified: after injecting
// a mutation, the tests still passed).
func PlatformKey(goos, goarch string) string {
	return nodePlatform(goos) + "/" + nodeArch(goarch)
}

// nodePlatform maps GOOS to the Node/electron-builder platform name
func nodePlatform(goos string) string {
	if goos == "windows" {
		return "win32"
	}
	return goos
}

// nodeArch maps GOARCH to the Node/electron-builder arch name
func nodeArch(goarch string) string {
	switch goarch {
	case "amd64":
		return "x64"
	case "386":
		return "ia32"
	default:
		return goarch
	}
}

// targetName is the executable file name for the target platform.
//
// rt.BinaryName can't be used: it reads the sidecar's OWN GOOS, while TasksFor generates tasks
// for the TARGET platform. Generating win32/x64 tasks on Linux would drop the .exe,
// leaving Windows users with extension-less executables — the same class of bug as the old win32/x64 naming bug.
func targetName(platform string, kind rt.Kind) string {
	name := string(kind)
	if len(platform) >= 5 && platform[:5] == "win32" {
		name += ".exe"
	}
	return name
}

// Tasks generates download tasks for the current platform; empty only means all dependencies.
func Tasks(managedDir string, only []string) ([]fetch.Task, error) {
	return TasksFor(CurrentPlatform(), managedDir, only)
}

// TasksFor is like Tasks, but with an explicit platform key.
//
// Exposed separately so the **full Windows download path can be verified on macOS** — issue #40's
// minimal repro is running `dp-deps.exe fetch --only ffmpeg` on Windows, which can't run
// Windows binaries locally. With this entry point, "win32/x64" can directly assert task generation.
func TasksFor(platform, managedDir string, only []string) ([]fetch.Task, error) {
	want := make(map[string]bool, len(only))
	for _, k := range only {
		want[k] = true
	}
	need := func(kind string) bool { return len(want) == 0 || want[kind] }

	var tasks []fetch.Task

	if need(string(rt.KindYtDlp)) {
		a, ok := ytdlpAssets[platform]
		if !ok {
			return nil, fmt.Errorf("yt-dlp downloads are not supported on %s", platform)
		}
		tasks = append(tasks, fetch.Task{
			Tool:   string(rt.KindYtDlp),
			URL:    ytdlpBase + "/" + a.Name,
			SHA256: a.SHA256,
			Target: filepath.Join(managedDir, targetName(platform, rt.KindYtDlp)),
		})
	}

	for _, kind := range []rt.Kind{rt.KindFFmpeg, rt.KindFFprobe} {
		if !need(string(kind)) {
			continue
		}
		byKind, ok := ffmpegAssets[platform]
		if !ok {
			return nil, fmt.Errorf("ffmpeg downloads are not supported on %s", platform)
		}
		a, ok := byKind[kind]
		if !ok {
			// No upstream build for Windows arm64 — skip instead of erroring
			continue
		}
		tasks = append(tasks, fetch.Task{
			Tool:   string(kind),
			URL:    ffmpegBase + "/" + a.Name + ".gz",
			SHA256: a.SHA256,
			Gzip:   true,
			Target: filepath.Join(managedDir, targetName(platform, kind)),
		})
	}

	if need(string(rt.KindGalleryDl)) {
		if a, ok := gallerydlAssets[platform]; ok {
			tasks = append(tasks, fetch.Task{
				Tool:   string(rt.KindGalleryDl),
				URL:    gallerydlBase + "/" + a.Name,
				SHA256: a.SHA256,
				Target: filepath.Join(managedDir, targetName(platform, rt.KindGalleryDl)),
			})
		}
	// Platforms like linux/arm64 with no upstream build: skip instead of erroring (yt-dlp fallback still works)
	}

	if need(string(rt.KindDeno)) {
		a, ok := denoAssets[platform]
		if !ok {
			return nil, fmt.Errorf("deno downloads are not supported on %s", platform)
		}
		inner := "deno"
		if platform == "win32/x64" {
			inner = "deno.exe"
		}
		tasks = append(tasks, fetch.Task{
			Tool:     string(rt.KindDeno),
			URL:      denoBase + "/" + a.Name,
			SHA256:   a.SHA256,
			Zip:      true,
			ZipInner: inner,
			Target:   filepath.Join(managedDir, targetName(platform, rt.KindDeno)),
		})
	}

	if len(tasks) == 0 {
		return nil, fmt.Errorf("no download tasks apply to %s", platform)
	}
	return tasks, nil
}
